import{state}from"./state.js";import{deleteHistoryEntryOnServer}from"./api.js";import{renderAll}from"./ui.js";import{showToast,showConfirm}from"./utils.js";import{applyServerFamilyData,flushPendingSave}from"./action-helpers.js";export function deleteHistoryItem(r){showConfirm("Удаление записи","Удалить эту запись из истории?",{onConfirm:()=>{(async()=>{await flushPendingSave();const e=await deleteHistoryEntryOnServer(r,state.currentChildId);e.success&&e.data?(applyServerFamilyData(e.data,{currentChildId:state.currentChildId}),renderAll(),showToast("Запись удалена","info")):showToast(e.error||"Не удалось удалить запись","error")})()}})}